    "\n"
    "        return select_gying_detail_cards_v11223(\n"
    "            raw_cards,\n"
    "            limit,\n"
    "            lambda candidate: bool(matcher(subscribe, candidate)),\n"
    "            expected_kind=expected_kind,\n"
    "            accepted_titles=accepted_titles,\n"
    "            expected_year=getattr(subscribe, \"year\", None),\n"
    "        )\n"
    "\n"
    "\n"
    "__all__ = [\n"
