    "\n"
    "\n"
    "def _html_to_text(fragment: str) -> str:\n"
    "    \"\"\"HTML 转文本时保留消息换行，避免相邻字段粘连。\"\"\"\n"
    "    value = re.sub(r\"<script\\b[^>]*>.*?</script>\", \" \", str(fragment or \"\"), flags=re.I | re.S)\n"
