    "\n"
    "from .legacy import _episode_numbers, _is_video, _safe_relative_path\n"
    "\n"
    "\n"
    "_TARGET_BOUND_PROCESSED_STATES = {\n"
    "    \"processed\",\n"
    "    \"transferred\",\n"
    "    \"synced\",\n"
    "    \"no_new_episode\",\n"
    "    \"legacy_synced\",\n"
    "}\n"
    "\n"
    "_AUXILIARY_DIR_NAMES = {\n"
    "    \"片头尾\",\n"
    "    \"片头片尾\",\n"
    "    \"片头\",\n"
    "    \"片尾\",\n"
    "    \"opening\",\n"
    "    \"ending\",\n"
    "    \"op\",\n"
    "    \"ed\",\n"
