    "\n"
    "def _nonnegative_int_v11219(value: Any) -> int:\n"
    "    try:\n"
    "        return max(0, int(value or 0))\n"
    "    except (TypeError, ValueError):\n"
    "        return 0\n"
    "\n"
    "\n"
    "def _nonnegative_float_v11219(value: Any) -> float:\n"
