    "\n"
    "    def _heal_selected_subscriptions_v1106(self) -> List[int]:\n"
    "        before = getattr(self, \"_selected_subscriptions\", [])\n"
    "        safe = selected_ids_v1106(before)\n"
    "        self._selected_subscriptions = safe\n"
    "        if before != safe:\n"
    "            try:\n"
    "                updater = getattr(self, \"update_config\", None)\n"
