    "        return super()._upsert_source(\n"
    "            sid,\n"
    "            uri,\n"
    "            label=label,\n"
    "            origin=origin,\n"
    "            enabled=enabled,\n"
    "            auto_dispatch=auto_dispatch,\n"
    "            **metadata,\n"
    "        )\n"
