    "\n"
    "\n"
    "def _is_browser_challenge_compat_failure_v1112(err: BaseException) -> bool:\n"
    "    \"\"\"仅识别 challenge/PoW 兼容失败；明确账号授权失败不冒充 fallback。\"\"\"\n"
    "    if isinstance(err, _GyingBrowserChallengeCompatFailureV1112):\n"
    "        return True\n"
    "    if isinstance(err, _GyingBrowserUnavailableV1112):\n"
    "        return False\n"
    "    if not isinstance(err, RuntimeError):\n"
    "        return False\n"
    "    text = str(err or \"\").strip().lower()\n"
    "    if not text:\n"
    "        return False\n"
    "    if any(marker in text for marker in _BROWSER_AUTH_HARD_FAIL_MARKERS_V1112):\n"
    "        return False\n"
    "    return any(marker in text for marker in _BROWSER_CHALLENGE_COMPAT_MARKERS_V1112)\n"
    "\n"
    "\n"
    "def _response_v1112(\n"
    "    url: str,\n"
    "    status: int,\n"
    "    text: str,\n"
    "    headers: Optional[Dict[str, Any]] = None,\n"
    ") -> requests.Response:\n"
    "    response = requests.Response()\n"
    "    response.status_code = int(status or 0)\n"
    "    response.url = str(url or \"\")\n"
    "    response.headers = CaseInsensitiveDict(\n"
    "        {str(key): str(value) for key, value in dict(headers or {}).items()}\n"
    "    )\n"
    "    response.encoding = \"utf-8\"\n"
    "    response._content = str(text or \"\").encode(\"utf-8\")\n"
    "    return response\n"
    "\n"
    "\n"
    "def _cookie_seed_v1112(cookie_header: str) -> str:\n"
    "    \"\"\"只恢复登录/业务 Cookie；浏览器绑定验证态必须由新 context 自己建立。\"\"\"\n"
    "    rows: List[str] = []\n"
    "    for raw in str(cookie_header or \"\").split(\";\"):\n"
    "        item = raw.strip()\n"
    "        if not item or \"=\" not in item:\n"
    "            continue\n"
    "        name, value = item.split(\"=\", 1)\n"
    "        name = name.strip()\n"
    "        value = value.strip()\n"
    "        if not name or not value or name.lower() in _BROWSER_BOUND_COOKIES_V1112:\n"
    "            continue\n"
    "        rows.append(f\"{name}={value}\")\n"
    "    return \"; \".join(rows)\n"
    "\n"
    "\n"
    "def _cookie_rows_v1112(cookie_header: str, node: str) -> List[Dict[str, str]]:\n"
    "    base = (canonical_gying_node(node) or str(node or \"\").rstrip(\"/\")).rstrip(\"/\") + \"/\"\n"
    "    rows: List[Dict[str, str]] = []\n"
    "    for raw in _cookie_seed_v1112(cookie_header).split(\";\"):\n"
    "        item = raw.strip()\n"
    "        if not item or \"=\" not in item:\n"
    "            continue\n"
    "        name, value = item.split(\"=\", 1)\n"
    "        if name.strip() and value.strip():\n"
    "            rows.append({\"name\": name.strip(), \"value\": value.strip(), \"url\": base})\n"
    "    return rows\n"
    "\n"
    "\n"
    "def _cookie_header_without_browser_state_v1112(session: requests.Session) -> str:\n"
    "    rows: List[str] = []\n"
    "    seen = set()\n"
    "    for cookie in list(session.cookies):\n"
    "        name = str(getattr(cookie, \"name\", \"\") or \"\").strip()\n"
    "        value = str(getattr(cookie, \"value\", \"\") or \"\").strip()\n"
    "        lowered = name.lower()\n"
    "        if (\n"
    "            not name\n"
    "            or not value\n"
    "            or lowered in _BROWSER_BOUND_COOKIES_V1112\n"
    "            or lowered in seen\n"
    "        ):\n"
    "            continue\n"
    "        rows.append(f\"{name}={value}\")\n"
    "        seen.add(lowered)\n"
    "    return \"; \".join(rows)\n"
    "\n"
    "\n"
    "def _same_origin_v1112(left: str, right: str) -> bool:\n"
    "    try:\n"
    "        a = urlparse(str(left or \"\"))\n"
    "        b = urlparse(str(right or \"\"))\n"
    "    except Exception:\n"
    "        return False\n"
    "    return (\n"
    "        a.scheme.lower(),\n"
    "        (a.hostname or \"\").lower(),\n"
    "        a.port,\n"
    "    ) == (\n"
    "        b.scheme.lower(),\n"
    "        (b.hostname or \"\").lower(),\n"
    "        b.port,\n"
    "    )\n"
    "\n"
    "\n"
    "def _status_from_navigation_v1112(navigation: Any) -> int:\n"
    "    value = getattr(navigation, \"status\", 200)\n"
    "    try:\n"
    "        value = value() if callable(value) else value\n"
    "        return int(value or 200)\n"
    "    except Exception:\n"
    "        return 200\n"
    "\n"
