    "        return f\"guangya-gying:{host}:{account}\"\n"
    "\n"
    "    def _gying_browser_close_row_v1112(self, row: Dict[str, Any]) -> None:\n"
    "        executor = row.get(\"executor\")\n"
    "        if not executor:\n"
    "            return\n"
    "\n"
    "        def closer() -> None:\n"
    "            page = row.get(\"page\")\n"
