    "\n"
    "    def _gying_browser_close_all_v1112(self) -> None:\n"
    "        registry = getattr(self, \"_gying_browser_registry_v1112\", None)\n"
    "        if not isinstance(registry, dict):\n"
    "            return\n"
    "        lock = getattr(self, \"_gying_browser_registry_lock_v1112\", threading.RLock())\n"
