    "                return {\n"
    "                    \"success\": False,\n"
    "                    \"message\": result.get(\"message\") or \"目标文件未确认可见\",\n"
    "                    \"verified_items\": verified,\n"
    "                }\n"
    "            verified.extend(result.get(\"verified_items\") or group)\n"
    "        return {\"success\": True, \"verified_items\": verified}\n"
    "\n"
