    "    r\"(?<=[\\u4e00-\\u9fff])(?:\\s|[·•:：\\-—_/])+?(?=[A-Za-z])|\"\n"
    "    r\"(?<=[A-Za-z])(?:\\s|[·•:：\\-—_/])+?(?=[\\u4e00-\\u9fff])\"\n"
    ")\n"
