    "\n"
    "\n"
    "def _title_segments_v11216(value: Any, expected_year: Any = None) -> List[Tuple[str, str]]:\n"
    "    \"\"\"抽取严格可解释的标题段；返回 (规范 key, 原始段)。\"\"\"\n"
