def _bootstrap_inline_modules() -> None:
    """在内存中恢复历史模块命名空间；仓库不再需要对应 .py 文件。"""
    package = __name__
    for short_name in _INLINE_MODULE_ORDER:
        full_name = f"{package}.{short_name}"
        module = sys.modules.get(full_name)
        if module is None:
            module = types.ModuleType(full_name)
            module.__file__ = f"{__file__}::{short_name}.py"
            module.__package__ = package
            module.__loader__ = globals().get("__loader__")
            module.__spec__ = None
            sys.modules[full_name] = module

    for short_name in _INLINE_MODULE_ORDER:
        full_name = f"{package}.{short_name}"
        module = sys.modules[full_name]
        if getattr(module, "__guangya_inline_loaded__", False):
            continue
        source = _INLINE_MODULE_SOURCES.get(short_name)
        if source is None:
            raise RuntimeError(f"光鸭转存助手内联模块缺失：{short_name}")
        code = compile(source, f"{__file__}::{short_name}.py", "exec")
        exec(code, module.__dict__)
        module.__guangya_inline_loaded__ = True


_bootstrap_inline_modules()

